// LoadDocumentConfirmations loads the sourceDocument's DocumentConfirmations into the .R struct
func (o *SourceDocument) LoadDocumentConfirmations(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if o == nil {
		return nil
	}

	// Reset the relationship
	o.R.DocumentConfirmations = nil
	o.R.Loaded.DocumentConfirmations = false

	related, err := o.DocumentConfirmations(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, rel := range related {
		rel.R.SourceDocument = o
		rel.R.Loaded.SourceDocument = true
	}

	o.R.DocumentConfirmations = related
	o.R.Loaded.DocumentConfirmations = true
	return nil
}

// LoadDocumentConfirmations loads the sourceDocument's DocumentConfirmations into the .R struct
func (os SourceDocumentSlice) LoadDocumentConfirmations(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	documentConfirmations, err := os.DocumentConfirmations(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		o.R.DocumentConfirmations = nil
		o.R.Loaded.DocumentConfirmations = true
	}
	// O(N+M) stitch via a map keyed by the join column (key -> []parent; was O(N*M)).
	sourceDocumentByKey := make(map[uuid.UUID][]*SourceDocument, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}

		sourceDocumentByKey[o.ID] = append(sourceDocumentByKey[o.ID], o)
	}

	for _, rel := range documentConfirmations {

		owners, ok := sourceDocumentByKey[rel.SourceDocumentID]
		if !ok {
			continue
		}

		for _, o := range owners {

			rel.R.SourceDocument = o
			rel.R.Loaded.SourceDocument = true

			o.R.DocumentConfirmations = append(o.R.DocumentConfirmations, rel)

		}
	}

	return nil
}

