// sourceDocumentC is where relationship counts are stored.
type sourceDocumentC struct {
	DocumentConfirmations *int64
	EvidenceLinks         *int64
	ExtractionJobs        *int64
}

// PreloadCount sets a count in the C struct by name
func (o *SourceDocument) PreloadCount(name string, count int64) error {
	if o == nil {
		return nil
	}

	switch name {
	case "DocumentConfirmations":
		o.C.DocumentConfirmations = &count
	case "EvidenceLinks":
		o.C.EvidenceLinks = &count
	case "ExtractionJobs":
		o.C.ExtractionJobs = &count
	}
	return nil
}

type sourceDocumentCountPreloader struct {
	DocumentConfirmations func(...bob.Mod[*dialect.SelectQuery]) psql.Preloader
	EvidenceLinks         func(...bob.Mod[*dialect.SelectQuery]) psql.Preloader
	ExtractionJobs        func(...bob.Mod[*dialect.SelectQuery]) psql.Preloader
}

func buildSourceDocumentCountPreloader() sourceDocumentCountPreloader {
	return sourceDocumentCountPreloader{
		DocumentConfirmations: func(mods ...bob.Mod[*dialect.SelectQuery]) psql.Preloader {
			return countPreloader[*SourceDocument]("DocumentConfirmations", func(parent string) bob.Expression {
				// Build a correlated subquery: (SELECT COUNT(*) FROM related WHERE fk = parent.pk)
				if parent == "" {
					parent = SourceDocuments.Alias()
				}

				subqueryMods := []bob.Mod[*dialect.SelectQuery]{
					sm.Columns(psql.Raw("count(*)")),

					sm.From(DocumentConfirmations.NameAsExpr()),
					sm.Where(psql.Quote(DocumentConfirmations.Alias(), "source_document_id").EQ(psql.Quote(parent, "id"))),
				}
				subqueryMods = append(subqueryMods, mods...)
				return psql.Group(psql.Select(subqueryMods...).Expression)
			})
		},
		EvidenceLinks: func(mods ...bob.Mod[*dialect.SelectQuery]) psql.Preloader {
			return countPreloader[*SourceDocument]("EvidenceLinks", func(parent string) bob.Expression {
				// Build a correlated subquery: (SELECT COUNT(*) FROM related WHERE fk = parent.pk)
				if parent == "" {
					parent = SourceDocuments.Alias()
				}

				subqueryMods := []bob.Mod[*dialect.SelectQuery]{
					sm.Columns(psql.Raw("count(*)")),

					sm.From(EvidenceLinks.NameAsExpr()),
					sm.Where(psql.Quote(EvidenceLinks.Alias(), "source_document_id").EQ(psql.Quote(parent, "id"))),
				}
				subqueryMods = append(subqueryMods, mods...)
				return psql.Group(psql.Select(subqueryMods...).Expression)
			})
		},
		ExtractionJobs: func(mods ...bob.Mod[*dialect.SelectQuery]) psql.Preloader {
			return countPreloader[*SourceDocument]("ExtractionJobs", func(parent string) bob.Expression {
				// Build a correlated subquery: (SELECT COUNT(*) FROM related WHERE fk = parent.pk)
				if parent == "" {
					parent = SourceDocuments.Alias()
				}

				subqueryMods := []bob.Mod[*dialect.SelectQuery]{
					sm.Columns(psql.Raw("count(*)")),

					sm.From(ExtractionJobs.NameAsExpr()),
					sm.Where(psql.Quote(ExtractionJobs.Alias(), "source_document_id").EQ(psql.Quote(parent, "id"))),
				}
				subqueryMods = append(subqueryMods, mods...)
				return psql.Group(psql.Select(subqueryMods...).Expression)
			})
		},
	}
}

